xpath.script:
(function() {
    function animateCounters() {
        var counters = document.querySelectorAll('.dimsop-counter-num[data-target]');
        if (!counters.length) return;
        counters.forEach(function(el) {
            if (el.getAttribute('data-animated') === 'true') return;
            el.setAttribute('data-animated', 'true');
            var target = parseInt(el.getAttribute('data-target'), 10);
            var duration = 1800;
            var startTime = null;
            var prefix = el.textContent.trim().charAt(0) === '+' ? '+' : '';
            function step(ts) {
                if (!startTime) startTime = ts;
                var progress = Math.min((ts - startTime) / duration, 1);
                var eased = 1 - Math.pow(1 - progress, 3);
                var current = Math.floor(eased * target);
                el.textContent = prefix + current;
                if (progress < 1) requestAnimationFrame(step);
                else el.textContent = prefix + target;
            }
            requestAnimationFrame(step);
        });
    }
    var obs = new IntersectionObserver(function(entries) {
        entries.forEach(function(entry) {
            if (entry.isIntersecting) animateCounters();
        });
    }, { threshold: 0.3 });
    document.addEventListener('DOMContentLoaded', function() {
        var section = document.getElementById('contadores');
        if (section) obs.observe(section);
        else setTimeout(function() {
            var s = document.getElementById('contadores');
            if (s) obs.observe(s);
        }, 500);
    });
})();

(function() {
    // Verificar prefers-reduced-motion
    var prefersReducedMotion = window.matchMedia &&
        window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    if (prefersReducedMotion) return;

    // Cargar GSAP + ScrollTrigger desde CDN
    function loadGSAP(callback) {
        if (window.gsap && window.ScrollTrigger) { callback(); return; }
        var gsapScript = document.createElement('script');
        gsapScript.src = 'https://cdn.jsdelivr.net/npm/gsap@3.12.5/dist/gsap.min.js';
        gsapScript.onload = function () {
            var stScript = document.createElement('script');
            stScript.src = 'https://cdn.jsdelivr.net/npm/gsap@3.12.5/dist/ScrollTrigger.min.js';
            stScript.onload = function () {
                gsap.registerPlugin(ScrollTrigger);
                callback();
            };
            document.head.appendChild(stScript);
        };
        document.head.appendChild(gsapScript);
    }

    function initAnimations() {
        gsap.config({ nullTargetWarn: false });

        /* HERO — Boot sequence (sin transformaciones en video) */
        gsap.from('.dimsop-hero-eyebrow-text', {
            opacity: 0, letterSpacing: '8px', duration: 0.8, delay: 0.2, ease: 'power2.out'
        });
        gsap.from('.dimsop-hero-eyebrow-line', {
            scaleX: 0, opacity: 0, duration: 0.6, delay: 0.3, stagger: 0.1, ease: 'power2.out'
        });
        gsap.from('#banner h1', { y: 40, opacity: 0, duration: 1, delay: 0.5, ease: 'power3.out' });
        gsap.from('#banner .dimsop-lead', { y: 30, opacity: 0, duration: 1, delay: 0.7, ease: 'power3.out' });

        /* ¿QUIÉNES SOMOS? — Timeline escalonada */
        var nosotrosTl = gsap.timeline({
            scrollTrigger: { trigger: '#nosotros', start: 'top 75%', toggleActions: 'play none none reverse' }
        });
        nosotrosTl
            .from('#nosotros .dimsop-h2', { y: 40, opacity: 0, duration: 0.8, ease: 'power3.out' })
            .from('#nosotros .dimsop-lead', { y: 25, opacity: 0, duration: 0.7, ease: 'power3.out' }, '-=0.5')
            .from('#nosotros .col-lg-6:first-child .dimsop-card', { x: -60, opacity: 0, duration: 0.8, ease: 'power3.out' }, '-=0.3')
            .from('#nosotros .col-lg-6:last-child .dimsop-card', { x: 60, opacity: 0, duration: 0.8, ease: 'power3.out' }, '-=0.6')
            .from('#nosotros .dimsop-h3', { y: 30, opacity: 0, duration: 0.6, ease: 'power3.out' }, '-=0.3')
            .from('#nosotros .text-center.mb-4', { y: 20, opacity: 0, duration: 0.5, ease: 'power3.out' }, '-=0.4')
            .from('#nosotros .dimsop-value', { scale: 0.85, opacity: 0, duration: 0.5, stagger: 0.08, ease: 'back.out(1.4)' }, '-=0.3');

        /* CINTILLO ISO */
        gsap.from('#iso', {
            x: -60, opacity: 0, duration: 0.7, ease: 'power3.out',
            scrollTrigger: { trigger: '#iso', start: 'top 90%', toggleActions: 'play none none reverse' }
        });

        /* METODOLOGÍA */
        gsap.from('#metodologia .dimsop-h2', {
            y: 50, opacity: 0, duration: 0.8, ease: 'power3.out',
            scrollTrigger: { trigger: '#metodologia', start: 'top 80%', toggleActions: 'play none none reverse' }
        });
        gsap.from('#metodologia .dimsop-step', {
            y: 40, opacity: 0, duration: 0.6, stagger: 0.12, ease: 'power3.out',
            scrollTrigger: { trigger: '#metodologia .row', start: 'top 85%', toggleActions: 'play none none reverse' }
        });

        /* UNIDADES DE NEGOCIO */
        gsap.from('#unidades .dimsop-h2', {
            y: 50, opacity: 0, duration: 0.8, ease: 'power3.out',
            scrollTrigger: { trigger: '#unidades', start: 'top 80%', toggleActions: 'play none none reverse' }
        });
        gsap.from('#unidades .dimsop-card', {
            y: 40, opacity: 0, duration: 0.6, stagger: 0.1, ease: 'power3.out',
            scrollTrigger: { trigger: '#unidades .row', start: 'top 85%', toggleActions: 'play none none reverse' }
        });

        /* MAPA DE COBERTURA */
        gsap.from('#cobertura .dimsop-h2', {
            y: 50, opacity: 0, duration: 0.8, ease: 'power3.out',
            scrollTrigger: { trigger: '#cobertura', start: 'top 80%', toggleActions: 'play none none reverse' }
        });
        gsap.from('#cobertura .dimsop-map-container', {
            scale: 0.92, opacity: 0, duration: 1, ease: 'power2.out',
            scrollTrigger: { trigger: '#cobertura .dimsop-map-container', start: 'top 85%', toggleActions: 'play none none reverse' }
        });

        /* ALIADOS */
        gsap.from('#aliados .dimsop-h2', {
            y: 50, opacity: 0, duration: 0.8, ease: 'power3.out',
            scrollTrigger: { trigger: '#aliados', start: 'top 80%', toggleActions: 'play none none reverse' }
        });

        /* CONTADORES */
        gsap.from('#contadores .dimsop-h2', {
            y: 50, opacity: 0, duration: 0.8, ease: 'power3.out',
            scrollTrigger: { trigger: '#contadores', start: 'top 80%', toggleActions: 'play none none reverse' }
        });

        /* PROYECTOS */
        gsap.from('#proyectos .dimsop-h2', {
            y: 50, opacity: 0, duration: 0.8, ease: 'power3.out',
            scrollTrigger: { trigger: '#proyectos', start: 'top 80%', toggleActions: 'play none none reverse' }
        });
        gsap.from('#proyectos .dimsop-project', {
            y: 40, opacity: 0, duration: 0.6, stagger: 0.1, ease: 'power3.out',
            scrollTrigger: { trigger: '#proyectos .row', start: 'top 85%', toggleActions: 'play none none reverse' }
        });

        /* BLOG */
        gsap.from('#blog .dimsop-h2', {
            y: 50, opacity: 0, duration: 0.8, ease: 'power3.out',
            scrollTrigger: { trigger: '#blog', start: 'top 80%', toggleActions: 'play none none reverse' }
        });
        gsap.from('#blog .dimsop-blog-card', {
            y: 30, opacity: 0, duration: 0.6, stagger: 0.12, ease: 'power3.out',
            scrollTrigger: { trigger: '#blog .row', start: 'top 85%', toggleActions: 'play none none reverse' }
        });

        /* FORMULARIO CONTACTO */
        gsap.from('#contacto .dimsop-h2', {
            y: 50, opacity: 0, duration: 0.8, ease: 'power3.out',
            scrollTrigger: { trigger: '#contacto', start: 'top 80%', toggleActions: 'play none none reverse' }
        });
        gsap.from('#contacto .dimsop-form', {
            y: 30, opacity: 0, duration: 0.7, ease: 'power3.out',
            scrollTrigger: { trigger: '#contacto .dimsop-form', start: 'top 85%', toggleActions: 'play none none reverse' }
        });

        /* FOOTER */
        gsap.from('#dimsop_footer .col-lg-4', {
            y: 30, opacity: 0, duration: 0.6, stagger: 0.12, ease: 'power3.out',
            scrollTrigger: { trigger: '#dimsop_footer', start: 'top 90%', toggleActions: 'play none none reverse' }
        });
    }

    loadGSAP(initAnimations);
})();

(function() {
    try {
        var t = localStorage.getItem('dimsop-theme');
        if (t === 'dark') document.documentElement.setAttribute('data-theme', 'dark');
    } catch(e) {}
})();

document.addEventListener('DOMContentLoaded', function() {
    var btn = document.getElementById('dimsop-dark-toggle');
    if (!btn) return;
    btn.addEventListener('click', function() {
        var isDark = document.documentElement.getAttribute('data-theme') === 'dark';
        var next = isDark ? 'light' : 'dark';
        document.documentElement.setAttribute('data-theme', next);
        try { localStorage.setItem('dimsop-theme', next); } catch(e) {}
        var icon = btn.querySelector('i');
        if (icon) {
            icon.className = next === 'dark' ? 'fa fa-sun-o' : 'fa fa-moon-o';
        }
    });
    // Sync icon on load
    var icon = btn.querySelector('i');
    if (icon && document.documentElement.getAttribute('data-theme') === 'dark') {
        icon.className = 'fa fa-sun-o';
    }
});
